import {RAIN_NOTEBOOK_PAGES,RAIN_NOTEBOOK_READ,RAIN_NOTEBOOK_QUANTITIES,RAIN_NOTEBOOK_UNIT,rainNotebookRows} from './rain-notebook-content.mjs';
import {rainNotebook,rainNotebookView,rainNotebookDisplayExposure,recoverRainNotebook,chooseRainNotebookCase,setRainNotebookPage,setRainNotebookReadPrompt,toggleRainNotebookRow,setRainNotebookQuantity,setRainNotebookBarInput,setRainNotebookValue,adjustRainNotebookBar,setRainNotebookModelInput,useRainNotebookSupport,checkRainNotebookData,checkRainNotebookChart,answerRainNotebookDraft,answerRainNotebookSource,answerRainNotebookModel,keepRainNotebookDraft} from './rain-notebook-core.mjs';
import {fieldNotebook} from './field-notebook-core.mjs';
import {RAIN_MODEL} from './rain-paths-content.mjs';
import {rainNotebookChartArt,rainNotebookPending} from './rain-notebook-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label={data:'Data',chart:'Build',read:'Read & check',keep:'Keep or revise'},readLabel={draft:'My bars',source:'Match the rows',model:'The question'};
const button=(attr,id,text,selected=false,kind='secondary')=>`<button type="button" class="${kind}${selected?' selected':''}" data-rn-${attr}="${esc(id)}" aria-pressed="${selected}">${esc(text)}</button>`;
const dom=id=>id.replace(':','-');
const same=(a,b)=>a===b||(Array.isArray(a)&&Array.isArray(b)&&a.length===b.length&&a.every((v,i)=>same(v,b[i])))||(a&&b&&typeof a==='object'&&typeof b==='object'&&!Array.isArray(a)&&!Array.isArray(b)&&Object.keys(a).length===Object.keys(b).length&&Object.keys(a).every(k=>Object.hasOwn(b,k)&&same(a[k],b[k])));
const content=s=>({caseId:s.caseId,source:s.source,question:s.question,selected:s.selected,values:s.values,pending:s.pending,quantity:s.quantity});
const currentTask=x=>x.views.page==='read'?x.views.readPrompt:x.views.page;
const origin=s=>s.origin==='kept-completed'?'Kept rain tray result':'Finished rain tray run';
function notice(source){return `<p class="rn-notice">${esc(source.result.model.notice)}</p>`;}
function rowsTable(rows,{remove=false}={}){return rows.length?`<div class="rn-source-rows" data-rn-outcomes>${rows.map(r=>`<div class="rn-source-row"><span>${esc(r.label)}</span><strong>${r.value}<small>${RAIN_NOTEBOOK_UNIT}</small></strong>${remove?`<button class="text-button" type="button" data-rn-row="${esc(r.id)}" aria-label="Remove ${esc(r.label)}">Remove</button>`:''}</div>`).join('')}</div>`:'<p>No rows chosen yet.</p>';}
function sourceDetails(source){const r=source.result,c=r.config;return `<details class="rn-source-details"><summary>For grown-ups: the full rain tray result and how it works</summary><p><strong>${esc(c.label)}</strong><br>${esc(origin(source))}. Changed factor: ${c.factor==='cover'?'entrance or lid':'starting stored water'}.</p><div class="rn-table-wrap" data-rn-outcomes><table><caption>Completed model result · new tokens on each tray</caption><thead><tr><th>Tray</th><th>Entrance / lid</th><th>Already stored</th><th>New input</th><th>Newly stored</th><th>New runoff</th></tr></thead><tbody>${r.rows.map(row=>`<tr><th>${row.id}</th><td>${row.cover==='open'?'Open entrance':'Sealed lid'}</td><td>${row.priorStored}</td><td>${row.newRainTotal}</td><td>${row.storedNew}</td><td>${row.runoffNew}</td></tr>`).join('')}</tbody></table></div><p>Both rain trays have ${r.model.capacity} storage slots, the same entrance geometry, outlet and collector. Each received ${c.newRainTotal} new tokens separately. Only the named factor changed.</p><p>Earlier stored water is starting context, not new rain or a new-water destination. Capacity: ${r.model.capacity} arbitrary tokens. Batch size: ${r.model.batchSize} arbitrary tokens, not a time unit.</p><p>${esc(RAIN_MODEL.limitation)}</p>${notice(source)}<p class="rn-small">Source model: ${esc(r.model.id)}. Earlier support and familiar work stay with this exact frozen record. This chart does not run the rain trays again.</p><details><summary>Original result provenance and source help</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details></details>`;}
function selectedSource(x){return `<section class="rn-selected-source"><h3>Your chosen rows</h3>${rowsTable(x.selectedRows,{remove:true})}<p class="rn-small">These counts stay the same when you change your chart.</p>${sourceDetails(x.source)}</section>`;}
function checkFeedback(x,task,kept=false){const c=x.checks[task];if(!c)return '';const outdated=!same(content(c.snapshot),content(x.snapshot)),parts=task==='chart'?[c.result.data.feedback,c.result.quantity.feedback,...c.result.bars.map(b=>b.feedback)]:[c.result.feedback];return `<section class="rn-feedback" id="${kept?`rn-kept-feedback-${task}`:'rn-feedback'}" tabindex="-1" role="status" data-rn-feedback-task="${task}" ${task==='model'||task==='chart'&&c.result.bars.length?'data-rn-outcomes':''}><p class="rn-earlier" data-rn-earlier ${outdated?'':'hidden'}><strong>You changed your chart.</strong> Check again to see new comments.</p>${parts.map(p=>`<p>${esc(p)}</p>`).join('')}<details class="grownup-note"><summary>For grown-ups</summary><p>Familiar practice with the source visible. The source’s earlier help and this chart’s help remain separate.${task==='model'?' These counts do not establish a real-world cause or safety verdict.':''}</p></details></section>`;}
function dataTask(x){return `<div class="rn-packet"><h3>Choose up to two rows</h3><p>Which rows answer the question about new runoff?</p><div class="rn-row-grid" data-rn-outcomes>${x.rows.map(r=>button('row',r.id,`${r.label}: ${r.value} ${RAIN_NOTEBOOK_UNIT}`,x.work.selected.includes(r.id))).join('')}</div><p id="rn-selection-status" role="status">${x.work.selected.length} of 2 selected. Remove a row before choosing another.</p></div><h3>Your selected pair</h3>${rowsTable(x.selectedRows,{remove:true})}<button class="primary" type="button" data-rn-check="data">Check my data</button>${checkFeedback(x,'data')}<p>${button('page','chart','Build a chart with these rows')}</p>${sourceDetails(x.source)}`;}
function barControls(x){return `<label class="rn-quantity">What does your chart show?<select data-rn-quantity><option value="">Not chosen yet</option>${RAIN_NOTEBOOK_QUANTITIES.map(q=>`<option value="${q.id}" ${x.work.quantity===q.id?'selected':''}>${q.label}</option>`).join('')}</select></label><p class="rn-small">Unit: ${RAIN_NOTEBOOK_UNIT}. Both bars use the same scale, from 0 to 24.</p>${x.selectedRows.map(r=>`<form class="rn-bar-form" data-rn-bar-form="${esc(r.id)}" novalidate><label for="rn-value-${dom(r.id)}">${esc(r.label)}</label><div class="rn-input-row"><input id="rn-value-${dom(r.id)}" name="value" type="text" inputmode="numeric" autocomplete="off" maxlength="16" value="${esc(x.work.pending.bars[r.id])}" placeholder="Blank" aria-describedby="rn-error-${dom(r.id)}"><button class="secondary" type="submit">Set bar</button><button class="text-button" type="button" data-rn-clear="${esc(r.id)}">Clear</button></div><div class="rn-adjust" role="group" aria-label="Adjust ${esc(r.label)}">${[-4,-1,1,4].map(n=>`<button class="secondary" type="button" data-rn-adjust="${esc(r.id)}|${n}" aria-label="${n<0?'Subtract':'Add'} ${Math.abs(n)} ${n<0?'from':'to'} ${esc(r.label)}">${n>0?'+':''}${n}</button>`).join('')}</div><p class="rn-error" id="rn-error-${dom(r.id)}" role="status"></p></form>`).join('')||'<p>Choose rows on Data to get bars to build.</p>'}`;}
function buildTask(x){return `<p>Type a number for each row. Press Set bar to update the picture. Check my chart sets every bar and checks them. Blank is different from zero.</p>${barControls(x)}<button class="primary" type="button" data-rn-check="chart">Check my chart</button><p class="rn-error" id="rn-chart-error" role="status"></p>${checkFeedback(x,'chart')}<p>${button('page','read','Read my chart')}</p>`;}
function readingTask(x){const task=x.views.readPrompt,c=x.checks[task],response=c&&same(content(c.snapshot),content(x.snapshot))?c.response:null;if(task==='draft')return `<p>Read the bars you made.</p><div class="rn-choices">${[['first','The first bar is longer'],['second','The second bar is longer'],['same','The bars have the same length']].map(([id,l])=>button('draft',id,l,response===id)).join('')}</div><p class="rn-small">Look at the number on each bar. A blank is different from zero.</p><p id="rn-read-error" class="rn-error" role="status"></p>${checkFeedback(x,'draft')}`;
 if(task==='source')return `<p>Do your two bars and your label match the rows you chose?</p><div class="rn-choices">${[['yes','Yes, they agree'],['differs','Something differs or is missing'],['unsure','I’m not sure yet']].map(([id,l])=>button('source',id,l,response===id)).join('')}</div>${checkFeedback(x,'source')}`;
 const target=x.question.targetIds.map(id=>x.rows.find(r=>r.id===id));return `<p>${esc(x.question.prompt)}</p><section class="rn-requested"><h3>The new runoff counts</h3>${rowsTable(target)}<p class="rn-small">These counts leave your bars as they are.</p></section><form id="rn-model-form" novalidate><fieldset><legend>Which tray had more new runoff?</legend>${[['A','Tray A'],['B','Tray B'],['same','The same amount'],['unsure','I’m not sure yet']].map(([id,l])=>`<label><input name="comparison" type="radio" value="${id}" ${x.work.pending.modelChoice===id?'checked':''}>${l}</label>`).join('')}</fieldset><label for="rn-difference">How many more tokens? (You can skip this.)<input id="rn-difference" name="difference" type="text" inputmode="numeric" autocomplete="off" maxlength="16" value="${esc(x.work.pending.difference)}" placeholder="Leave blank if you like"></label><button class="primary" type="submit">Check my answer</button><p id="rn-model-error" class="rn-error" role="status"></p></form>${checkFeedback(x,'model')}`;}
function keptContent(k){return `<h3>Kept chart · ${esc(k.draft.source.result.config.label)}</h3>${rainNotebookChartArt(k.draft)}<details><summary>What you typed and checked</summary>${rainNotebookRows(k.draft.source).filter(r=>k.draft.selected.includes(r.id)).map(r=>`<p>${esc(r.label)}, typed entry: <code>${esc(k.draft.pending.bars[r.id])||'(blank)'}</code>; applied value: ${k.draft.values[r.id]===null?'blank':k.draft.values[r.id]}.</p>`).join('')}<p>Original-question choice: ${esc(({A:'Tray A',B:'Tray B',same:'The same amount',unsure:'Not sure'})[k.draft.pending.modelChoice]||'not chosen')}. Optional difference: <code>${esc(k.draft.pending.difference)||'(blank)'}</code>.</p>${Object.keys(k.checks).map(task=>checkFeedback({checks:k.checks,snapshot:k.draft},task,true)).join('')}</details>${sourceDetails(k.draft.source)}<p class="rn-small">${k.revised?'A changed kept chart.':'Your first kept chart.'}</p><details class="grownup-note"><summary>For grown-ups</summary><p>Keeping is not passing, a new experiment or independent transfer.</p></details>`;}
function keepTask(x){return `<p>You can keep an unfinished chart, a surprising pair, or something you want to change.</p><button class="primary" type="button" data-rn-keep>Keep this chart</button><p>${button('page','chart','Change my chart')}</p>${x.work.kept?`<section class="rn-kept" id="rn-kept" tabindex="-1">${keptContent(x.work.kept)}</section>`:'<p id="rn-kept" tabindex="-1">No chart kept for this case yet.</p>'}<p>Tell someone: “I chose these rows because…” or “I would change…”</p><details class="grownup-note"><summary>For grown-ups</summary><p>Keeping does not mean passing. Your conversation is not graded or recorded.</p></details>`;}
function support(x){const task=currentTask(x),flags=x.work.support[task]||{},help=task==='data'?'The question asks about new runoff. Choose new runoff once for Tray A and once for Tray B. Already stored water was there at the start.':task==='chart'?'Use the labels of the rows you chose. Type a whole number from 0 to 24, or leave it blank. Stored-water rows answer a different question.':task==='draft'?'Read the bars you made. A zero is a number. A blank is waiting.':task==='source'?'Check each number and the label against the row you chose.':task==='model'?'Use the two new runoff counts. Compare them. They tell us about the rain trays, not a real flood.':'You can keep a question or a half-finished idea. Your counts stay with the kept chart.';return `<aside class="rn-support" tabindex="-1"><div class="rn-controls">${button('support','help','A useful clue')}${button('support','together','We’re working together',!!flags.together).replace('working together</button>',`working together${flags.together?' <span aria-hidden="true">✓</span>':''}</button>`)}<span data-rn-audio>${hearButton(task==='data'||task==='model'?x.question.prompt:help,'Hear this turn')}</span></div>${flags.help?`<p id="rn-help" tabindex="-1">${esc(help)}</p>`:''}</aside>`;}
export function rainNotebookEntry(){return '<aside class="rn-entry"><div><h2>Rain charts</h2><p>Go back to a finished rain tray result and make its numbers visible.</p></div><a class="secondary" href="#living/notebook/rain">Open Rain charts</a></aside>';}
export function rainNotebookPage(state){const x=rainNotebookView(state);if(!x){const outer=fieldNotebook(state);return `<section class="rn-workspace rn-unavailable"><h1 id="rn-title" tabindex="-1">An earlier rain chart record is kept</h1><p>This format cannot be opened here. The original record stays in notes downloads.</p>${outer?'<button class="secondary" type="button" data-rn-recover>Keep the earlier rain chart record and start fresh</button>':'<p>The whole notebook has an unavailable format. <a href="#living/notebook">Open the notebook’s recovery choices</a>.</p>'}<p><a href="#science/rain">Return to Rain Paths</a> · <a href="#notes">Grown-up notes</a></p></section>`;}
 if(!x.work)return '<section class="rn-workspace"><h1 id="rn-title" tabindex="-1">Rain charts</h1><p>Bring a finished rain tray result here to choose rows and build a chart.</p><p>At Rain Paths, finish a rain tray run. Then press Make a rain chart. Half-finished runs and planning copies cannot be charted.</p><a class="primary" href="#science/rain">Go to the rain trays</a><p><a href="#living/notebook">Seedling charts</a></p></section>';
 const page=x.views.page,task=currentTask(x),title=page==='data'?'Which data answer our question?':page==='chart'?'Make the counts visible':page==='keep'?'Something to keep or change?':x.views.readPrompt==='draft'?'Which of your bars is longer?':x.views.readPrompt==='source'?'Does your chart match your rows?':'Answer the runoff question',r=rainNotebook(state);
 return `<div class="rn-workspace rn-page-${page}" data-rn-task="${task}"><header><a class="back" href="#science/rain">Back to Rain Paths</a><h1>Rain charts</h1><p>A result you know, a new way to look.</p></header><section class="rn-question"><strong>${esc(x.source.result.config.label)}</strong><p>${esc(x.question.prompt)}</p><p class="rn-small">${esc(origin(x.source))}. ${x.source.result.config.newRainTotal} new tokens on each tray. Your rain trays and Seedling charts stay separate.</p></section><nav class="rn-pages" aria-label="Rain chart pages">${RAIN_NOTEBOOK_PAGES.map((id,i)=>button('page',id,`${i+1}. ${label[id]}`,page===id)).join('')}</nav><h2 id="rn-title" tabindex="-1">${esc(title)}</h2>${page==='read'?`<div class="rn-read-tabs" role="group" aria-label="Rain chart reading prompts">${RAIN_NOTEBOOK_READ.map(id=>button('read',id,readLabel[id],x.views.readPrompt===id)).join('')}</div>`:''}<div class="rn-layout"><section class="rn-task">${page==='data'?dataTask(x):page==='chart'?buildTask(x):page==='read'?readingTask(x):keepTask(x)}</section>${page==='data'?'':`<aside class="rn-reference">${rainNotebookChartArt(x.snapshot)}${selectedSource(x)}</aside>`}</div>${support(x)}<details class="rn-cases"><summary>Choose another rain tray result</summary><div class="rn-controls">${Object.keys(r.cases).map(id=>button('case',id,r.cases[id].source.result.config.label,id===x.caseId)).join('')}</div><p class="rn-small">Only results you brought here are listed. Each case keeps its own chart and page.</p></details><footer><a href="#science/rain">Rain trays</a><a href="#living/notebook">Seedling charts</a><a href="#home">Take a break</a><a href="#notes">Grown-up notes</a></footer></div>`;}
export function bindRainNotebook(state,ctx){const root=document.querySelector('.rn-workspace');if(!root)return;const emit=()=>{const exposure=rainNotebookDisplayExposure(state);exposure.results=[...root.querySelectorAll('[data-rn-outcomes]')].some(el=>el.getClientRects().length>0);if(exposure.results||exposure.unknown)ctx.expose?.(exposure);};root.querySelectorAll('details').forEach(el=>el.addEventListener('toggle',emit));emit();const overflow=new Set();const error=(id,text)=>{const el=root.querySelector(id);if(el){el.textContent=text;ctx.focus?.(id);}};const redraw=(target='#rn-title')=>{ctx.save();ctx.render();ctx.focus?.(target);};const guard=()=>{if(!overflow.size)return true;error(overflow.has('difference')?'#rn-model-error':`#rn-error-${dom([...overflow][0])}`,'An entry is longer than 16 characters. Edit it before leaving; your text is still visible.');return false;};const act=(fn,target)=>{if(!guard())return;const r=fn();if(r!==false)redraw(target);};
 root.querySelector('[data-rn-recover]')?.addEventListener('click',()=>act(()=>recoverRainNotebook(state)));const x=rainNotebookView(state);if(!x?.work)return;
 const task=()=>currentTask(rainNotebookView(state));
 const updateDraftLabels=()=>{const view=rainNotebookView(state);root.querySelectorAll('.rn-pending-notice').forEach(n=>n.hidden=!rainNotebookPending(view.snapshot));root.querySelectorAll('[data-rn-feedback-task]').forEach(el=>{const check=view.checks[el.dataset.rnFeedbackTask],marker=el.querySelector('[data-rn-earlier]');if(check&&marker)marker.hidden=same(content(check.snapshot),content(view.snapshot));});};
 root.querySelectorAll('[data-rn-page]').forEach(b=>b.onclick=()=>act(()=>setRainNotebookPage(state,b.dataset.rnPage)));
 root.querySelectorAll('[data-rn-read]').forEach(b=>b.onclick=()=>act(()=>setRainNotebookReadPrompt(state,b.dataset.rnRead)));
 root.querySelectorAll('[data-rn-case]').forEach(b=>b.onclick=()=>act(()=>chooseRainNotebookCase(state,b.dataset.rnCase)));
 root.querySelectorAll('[data-rn-row]').forEach(b=>b.onclick=()=>{if(!guard())return;if(toggleRainNotebookRow(state,b.dataset.rnRow)!==false)redraw();else error('#rn-selection-status','Two rows are already selected. Remove one to choose another.');});
 root.querySelector('[data-rn-quantity]')?.addEventListener('change',e=>act(()=>setRainNotebookQuantity(state,e.target.value||null),'[data-rn-quantity]'));
 root.querySelectorAll('[data-rn-bar-form] input').forEach(input=>input.addEventListener('input',()=>{const id=input.closest('form').dataset.rnBarForm;if(setRainNotebookBarInput(state,id,input.value)){overflow.delete(id);ctx.save();updateDraftLabels();}else{overflow.add(id);const status=root.querySelector(`#rn-error-${dom(id)}`);if(status)status.textContent='Keep at most 16 characters in this entry. Nothing was shortened; edit it before leaving.';}}));
 const parse=text=>{const t=text.trim();return t===''?{valid:true,value:null}:/^(?:0|[1-9]\d?)$/.test(t)&&Number(t)<=24?{valid:true,value:Number(t)}:{valid:false};};
 root.querySelectorAll('[data-rn-bar-form]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();if(!guard())return;const id=form.dataset.rnBarForm,p=parse(rainNotebookView(state).work.pending.bars[id]);if(!p.valid){error(`#rn-error-${dom(id)}`,'Enter a whole number from 0 to 24, or Clear this bar. Your entry is still here.');return;}act(()=>setRainNotebookValue(state,id,p.value),`#rn-value-${dom(id)}`);}));
 root.querySelectorAll('[data-rn-clear]').forEach(b=>b.onclick=()=>{const id=b.dataset.rnClear;if(overflow.size>1||overflow.size===1&&!overflow.has(id)){guard();return;}overflow.delete(id);act(()=>setRainNotebookValue(state,id,null),`#rn-value-${dom(id)}`);});
 root.querySelectorAll('[data-rn-adjust]').forEach(b=>b.onclick=()=>{if(!guard())return;const [id,n]=b.dataset.rnAdjust.split('|'),r=adjustRainNotebookBar(state,id,Number(n));if(r&&r.valid)redraw(`#rn-value-${dom(id)}`);else if(r)error(`#rn-error-${dom(id)}`,r.error);});
 root.querySelectorAll('[data-rn-check]').forEach(b=>b.onclick=()=>{if(!guard())return;if(b.dataset.rnCheck==='data'){if(checkRainNotebookData(state))redraw('#rn-feedback');}else{const r=checkRainNotebookChart(state);if(r?.valid)redraw('#rn-feedback');else if(r)error('#rn-chart-error',r.error);}});
 root.querySelectorAll('[data-rn-draft]').forEach(b=>b.onclick=()=>{if(!guard())return;if(answerRainNotebookDraft(state,b.dataset.rnDraft))redraw('#rn-feedback');else error('#rn-read-error','Set both bars on Build first. Blank is different from zero.');});
 root.querySelectorAll('[data-rn-source]').forEach(b=>b.onclick=()=>act(()=>answerRainNotebookSource(state,b.dataset.rnSource),'#rn-feedback'));
 root.querySelectorAll('#rn-model-form input[name=comparison]').forEach(input=>input.addEventListener('change',()=>{if(setRainNotebookModelInput(state,'choice',input.value)){ctx.save();updateDraftLabels();}}));
 root.querySelector('#rn-difference')?.addEventListener('input',e=>{if(setRainNotebookModelInput(state,'difference',e.target.value)){overflow.delete('difference');ctx.save();updateDraftLabels();}else{overflow.add('difference');const status=root.querySelector('#rn-model-error');if(status)status.textContent='Keep at most 16 characters in the difference. Nothing was shortened.';}});
 root.querySelector('#rn-model-form')?.addEventListener('submit',e=>{e.preventDefault();if(!guard())return;const r=answerRainNotebookModel(state);if(r?.valid)redraw('#rn-feedback');else if(r)error('#rn-model-error',r.error);});
 root.querySelectorAll('[data-rn-support]').forEach(b=>b.onclick=()=>act(()=>useRainNotebookSupport(state,task(),b.dataset.rnSupport),b.dataset.rnSupport==='help'?'#rn-help':'.rn-support'));
 root.querySelectorAll('[data-rn-audio] [data-speak]').forEach(b=>b.addEventListener('click',()=>{useRainNotebookSupport(state,task(),'audio');ctx.save();}));
 root.querySelector('[data-rn-keep]')?.addEventListener('click',()=>act(()=>keepRainNotebookDraft(state),'#rn-kept'));
}
export function rainNotebookNotes(state){const outer=state.fieldNotebook;if(!outer||typeof outer!=='object'||!Object.hasOwn(outer,'rain'))return '';return `<details class="panel rn-notes" data-rn-notes><summary>Rain Paths charts</summary><p>Charts reuse frozen completed rain tray results. Row relevance, faithful copying, reading a draft and answering from a source remain distinct familiar practice. Applied and pending entries, original source support and chart support stay separate. No real rainfall, flood forecast, safety verdict or independent transfer is inferred.</p><pre>${esc(JSON.stringify(outer.rain,null,2))}</pre></details>`;}
